-- Keep global statistics consistent with LexiMind's evidence-based learning states.
create or replace function public.user_stats() returns jsonb language sql stable as $$
with u as(select coalesce(sum(visits),0) visits,coalesce(sum(active_seconds),0) seconds,count(distinct day) filter(where active_seconds>0) active_days,max(day) last_day,coalesce(sum(active_seconds) filter(where area='leximind'),0) lexi_seconds,coalesce(sum(active_seconds) filter(where area='table'),0) table_seconds,coalesce(sum(active_seconds) filter(where area='portal'),0) portal_seconds from user_usage_daily where user_id=auth.uid()),
l as(select count(*) seen,count(*) filter(where reviews>=3 and (reviews-lapses)>=2 and level>=2) learned,count(*) filter(where reviews>=5 and (reviews-lapses)>=4 and level>=4 and lapses<=greatest(1,reviews/4)) mastered,coalesce(sum(reviews),0) reviews,coalesce(sum(lapses),0) lapses from lexi_progress where user_id=auth.uid()),
g as(select count(*) games,count(*) filter(where r.winner_id=auth.uid()) wins from game_players p join game_results r on r.id=p.result_id where p.user_id=auth.uid())
select jsonb_build_object('visits',u.visits,'active_seconds',u.seconds,'active_days',u.active_days,'last_day',u.last_day,'lexi_seconds',u.lexi_seconds,'table_seconds',u.table_seconds,'portal_seconds',u.portal_seconds,'seen',l.seen,'learned',l.learned,'mastered',l.mastered,'reviews',l.reviews,'retention',round((100*(l.reviews-l.lapses)/greatest(l.reviews,1))::numeric,1),'words_per_hour',round((l.learned*3600.0/greatest(u.lexi_seconds,1))::numeric,1),'games',g.games,'wins',g.wins,'win_rate',round((100.0*g.wins/greatest(g.games,1))::numeric,1),'games_per_hour',round((g.games*3600.0/greatest(u.table_seconds,1))::numeric,1),'avg_visit_minutes',round((u.seconds/60.0/greatest(u.visits,1))::numeric,1)) from u,l,g $$;